func TestAdd(t *testing.T) {
  cases := []struct{a, b, want int}{
    {1,2,3}, {2,3,5},
  }
  for _, c := range cases {
    got := Add(c.a, c.b)
    if got != c.want { t.Errorf("got %d, want %d", got, c.want) }
  }
}
func BenchmarkAdd(b *testing.B) {
  for i := 0; i < b.N; i++ { Add(1,2) }
}

